INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(52111, 'Genesis 32:28', 'Genesis', 32, 28, 'هغه کس وویل: «له دې وروسته به نور ستا نوم یعقوب نه وي، بلکې اسراییل به وي، ځکه چې تا د خدای او انسان سره غېږه ونیوله او بریالی شوې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_28.mp3', '', 1761754199, 1761754199),
(52112, 'Genesis 32:29', 'Genesis', 32, 29, 'یعقوب وویل: «خپل نوم دې ماته ووایه.» خو هغه ځواب ورکړ: «ولې زما د نوم پوښتنه کوې؟» نو په هغه ځای کې یې یعقوب ته برکت ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_29.mp3', '', 1761754199, 1761754199),
(52113, 'Genesis 32:30', 'Genesis', 32, 30, 'نو یعقوب وویل: «خدای مې مخامخ ولیده او لا تر‌اوسه هم ژوندی پاتې یم.» نو یعقوب هغه ځای د فنییل په نوم یاد کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_30.mp3', '', 1761754199, 1761754199),
(52114, 'Genesis 32:31', 'Genesis', 32, 31, 'د لمرخاته په وخت کې هغه د فنییل څخه تېر شو او د خپل ورون په سبب یې ګوډ، ګوډ تګ کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_31.mp3', '', 1761754199, 1761754199),
(52115, 'Genesis 32:32', 'Genesis', 32, 32, 'په همدې خاطر اسراییلیان تر نن ورځې پورې هغه پله چې د ورون د بنده پورې نښتې ده نه خوري، ځکه چې د یعقوب د ورون همدې برخې ګوزار خوړلی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis32_verse_32.mp3', '', 1761754199, 1761754199),
(52116, 'Isaiah 30:1', 'Isaiah', 30, 1, 'څښتن ویلي دي: «افسوس د یاغي زامنو په حال! ځکه هغوی له ما سره مشوره نه کوي او خپلې نقشې جوړوي. زما د خوښۍ او رضا په خلاف د نورو سره تړون کوي او په دې ډول د خپلو ګناهونو بار ډېروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_1.mp3', '', 1761754199, 1761754199),
(52117, 'Isaiah 30:2', 'Isaiah', 30, 2, 'هغوی بې له دې چې زما سره مشوره وکړي د مرستې په خاطر مصر ته ځي. هغوی له فرعونه غواړي چې د دوی ساتنه وکړي او هغوی د مصر سیوري ته پناه وړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_2.mp3', '', 1761754199, 1761754199),
(52118, 'Isaiah 30:3', 'Isaiah', 30, 3, 'خو په فرعون توکل به د هغوی د شرم او د مصر سیوري ته پناه وړل به د هغوی د رسوایۍ سبب وګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_3.mp3', '', 1761754199, 1761754199),
(52119, 'Isaiah 30:4', 'Isaiah', 30, 4, 'که څه هم د یهودا د پاچا استازي لا د مخکې نه د مصر د صوعن او حانیس ښارونو ته رسېدلي دي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_4.mp3', '', 1761754199, 1761754199),
(52120, 'Isaiah 30:5', 'Isaiah', 30, 5, 'د یهودا قوم به وشرمیږي او رسوا به شي چې هغوی په یو بې باوره هېواد باندې باور وکړ. ځکه هغوی ورڅخه د مرستې تمه لرله، خو هغه هېواد د هغوی سره هېڅ مرسته ونه کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_5.mp3', '', 1761754199, 1761754199),
(52121, 'Isaiah 30:6', 'Isaiah', 30, 6, 'دا د څښتن هغه پیغام دی چې د جنوبي دښتې د حیواناتو په اړه دی: دا استازي د هغه وطن په لاره سفر کوي چې خطرناک او د ستونزو څخه ډک دی، چې هلته زمریان او زهرجن او ټوپ وهونکي ماران اوسیږي. هغوی خپل خره او اوښان په قیمتي سوغاتونو بار کړي دي او هغه هېواد ته یې وړي چې د هغوی سره مرسته نه شي کولای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_6.mp3', '', 1761754199, 1761754199),
(52122, 'Isaiah 30:7', 'Isaiah', 30, 7, 'د مصر مرسته ګټه نه لري. نو ځکه ما مصر ته د «د سیند د لویې او بېکاره بلا» لقب ورکړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_7.mp3', '', 1761754199, 1761754199),
(52123, 'Isaiah 30:8', 'Isaiah', 30, 8, 'څښتن ماته وویل: «اوس لاړ شه، د هغوی په وړاندې دا ټولې پېښې د یوې تیږې په لوحې او یا په یو طومار کې د تلپاتې نښې په توګه ولیکه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_8.mp3', '', 1761754199, 1761754199),
(52124, 'Isaiah 30:9', 'Isaiah', 30, 9, 'هغوی تل د څښتن په وړاندې سرغړونه کوي، دروغجن دي او د هغه د تعلیم د منلو څخه انکار کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_9.mp3', '', 1761754199, 1761754199),
(52125, 'Isaiah 30:10', 'Isaiah', 30, 10, 'هغوی نبیانو ته وایي: ‹رویاګانې مه ګورئ. مونږ ته د رښتینولۍ په اړه خبرې مه کوئ. مونږ ته هغه خبرې وکړئ چې اورېدل یې غواړو. خیر دی که هغه دروغ هم وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_10.mp3', '', 1761754199, 1761754199),
(52126, 'Isaiah 30:11', 'Isaiah', 30, 11, 'زمونږ له لارې نه اخوا شئ او زمونږ مخه مه نیسئ. مونږ نه غواړو چې د اسراییلو د سپېڅلي خدای په اړه څه واورو.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_11.mp3', '', 1761754199, 1761754199),
(52127, 'Isaiah 30:12', 'Isaiah', 30, 12, 'په دې خاطر د اسراییلو سپېڅلی خدای داسې وایي: «زه چې څه وایم هغه تاسو نه منئ او په ظلم او غولونې باندې تکیه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_12.mp3', '', 1761754199, 1761754199),
(52128, 'Isaiah 30:13', 'Isaiah', 30, 13, 'تاسو ګناهکاران یئ. تاسو د هغه لوړ دېوال په شان یئ چې درز یې کړی وي او دا دېوال به ډېر زر ناڅاپه راوغورځیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_13.mp3', '', 1761754199, 1761754199),
(52129, 'Isaiah 30:14', 'Isaiah', 30, 14, 'دا دېوال به لکه د خاورین لوښي په شان ټوټې ټوټې شي، داسې په بې رحمۍ سره به ټوټې ټوټې شي چې یوه ټوټه به یې هم داسې غټه نه وي چې د نغري نه ورباندې بل سکاره راواخیستلی شي او یا په کې د ډنډ څخه اوبه راوویستل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_14.mp3', '', 1761754199, 1761754199),
(52130, 'Isaiah 30:15', 'Isaiah', 30, 15, 'څښتن تعالی د اسراییلو سپېڅلی خدای خلکو ته داسې وایي: «زما خواته راستانه شئ او په ما باندې باور وکړئ ترڅو وژغورل شئ. بیا به تاسو قوي، ارام او په امن کې اوسئ.» خو تاسو دا ونه غوښتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_15.mp3', '', 1761754199, 1761754199),
(52131, 'Isaiah 30:16', 'Isaiah', 30, 16, 'د دې په ځای، تاسو پلان لرئ چې په تېزو اسونو باندې سپاره شئ او د خپلو دښمنانو څخه وتښتئ. تاسو په حقه یئ، باید وتښتئ. تاسو فکر کوئ چې ستاسو اسونه تېز دي، خو د هغو خلکو اسونه چې په تاسو پسې دي هغه ستاسو د اسونو څخه ډېر تېز دي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_16.mp3', '', 1761754199, 1761754199),
(52132, 'Isaiah 30:17', 'Isaiah', 30, 17, 'کله چې تاسو د دښمن یو عسکر ووینئ، نو ستاسو زر کسان به ورڅخه وتښتي. پنځه عسکر ستاسو د ټولو د ځغلولو دپاره بس دي. ستاسو د لښکر څخه به د غره په سر د بیرغ د لرګي پرته نور هېڅ شی پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_17.mp3', '', 1761754199, 1761754199),
(52133, 'Isaiah 30:18', 'Isaiah', 30, 18, 'خو بیاهم څښتن دې ته انتظار کوي چې په تاسو باندې مهربان شي. هغه تیار دی چې په تاسو رحم وکړي، ځکه چې څښتن عادل خدای دی. هغه خلک بختور دي چې په څښتن باندې توکل کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_18.mp3', '', 1761754199, 1761754199),
(52134, 'Isaiah 30:19', 'Isaiah', 30, 19, 'ای د صهیون خلکو چې په اورشلیم کې اوسېږئ، تاسو به نور ونه ژاړئ. څښتن رحیم دی او څنګه چې هغه ستاسو ژړا او چیغې واوري، نو په تاسو به رحم وکړي او ستاسو غوښتنه به ومني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_19.mp3', '', 1761754199, 1761754199),
(52135, 'Isaiah 30:20', 'Isaiah', 30, 20, 'که څه هم څښتن تاسو ته د ډوډۍ او اوبو دپاره تکلیف درکړی دی، بیاهم هغه ستاسو ښوونکی دی او نور به ستاسو څخه خپل ځان نه پټوي. تاسو به په خپلو سترګو هغه ووینئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_20.mp3', '', 1761754199, 1761754199),
(52136, 'Isaiah 30:21', 'Isaiah', 30, 21, 'که چېرې له تاسو لاره ورکه شي چې ښي خواته لاړ شئ یا چپ خواته، ستاسو غوږونه به د شا له خوا د هغه اواز واوري: «لاره دا ده، په دې لاره لاړ شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_21.mp3', '', 1761754199, 1761754199),
(52137, 'Isaiah 30:22', 'Isaiah', 30, 22, 'بیا به تاسو خپل هغه بتان چې په سپینو او سرو زرو باندې پوښل شوي دي لکه د نجس شي په شان لېرې ګوزار کړئ او وبه وایئ: «زمونږ د مخې نه لېرې شئ!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_22.mp3', '', 1761754199, 1761754199),
(52138, 'Isaiah 30:23', 'Isaiah', 30, 23, 'هرکله چې تاسو تخمونه کرئ نو څښتن به باران را اوروي چې هغه راشنه شي او تاسو ته به پرېمانه حاصلات درکړي. هغه وخت به ستاسو د څارویو د پوولو دپاره پراخه څړځایونه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_23.mp3', '', 1761754199, 1761754199),
(52139, 'Isaiah 30:24', 'Isaiah', 30, 24, 'کوم غویان او خره چې ستاسو په پټیو کې قلبه کوي هغوی به ډېر ښه خوراک چې په بېلچې او درې غاښي ښاخۍ سره پاک شوی دی، وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_24.mp3', '', 1761754199, 1761754199),
(52140, 'Isaiah 30:25', 'Isaiah', 30, 25, 'کله چې ستاسو دښمنان ووژل شي او لوړ برجونه یې راوغورځیږي، په هغه ورځ به ستاسو دپاره د اوبو ویالې له هره غره څخه او له هرې غونډۍ څخه جاري شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_25.mp3', '', 1761754199, 1761754199),
(52141, 'Isaiah 30:26', 'Isaiah', 30, 26, 'د سپوږمۍ رڼا به د لمر په شان وي او د لمر رڼا به اووه ځلې زیاته شي او داسې به وي لکه په یوه ورځ کې چې د اوو ورځو رڼا راشي. دا به هغه وخت وشي چې څښتن د خپلو خلکو هډوکي چې مات کړي یې دي وتړي او په هغو ټپونو باندې چې خپلو خلکو ته یې ورکړي دي د ملهم پټۍ کېږدي او هغوی روغ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_26.mp3', '', 1761754199, 1761754199),
(52142, 'Isaiah 30:27', 'Isaiah', 30, 27, 'وګورئ، د څښتن واک او جلال د لېرې ځای څخه ښکاري. اور او تور لوګی د هغه د غوسې نښه ده. هغه خبرې کوي او د هغه وینا د اور په شان سوځوونکې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_27.mp3', '', 1761754199, 1761754199),
(52143, 'Isaiah 30:28', 'Isaiah', 30, 28, 'د هغه ساه لکه د سېلاب په شان ده چې اوبه یې تر ستوني پورې رسیږي. هغه به قومونه چاڼ او غلبېل کړي چې ورک یې کړي. هغه به د هغوی په خوله کې قیضه واچوي او د تباهۍ خواته به یې یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_28.mp3', '', 1761754199, 1761754199),
(52144, 'Isaiah 30:29', 'Isaiah', 30, 29, 'خو ای د څښتن قومه! تاسو به خوشحاله یئ او داسې سندرې به ووایئ لکه د سپېڅلي اختر په شپه یې چې وایئ. تاسو به د هغو خلکو په شان خوشحاله یئ چې د شپېلۍ په وهلو سره د څښتن کور ته روان وي، د هغه چا کور چې د اسراییلو ساتونکی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_29.mp3', '', 1761754199, 1761754199),
(52145, 'Isaiah 30:30', 'Isaiah', 30, 30, 'څښتن به خپل د شان او شوکت نه ډک اواز د هر چا غوږ ته ورسوي او د خپل قهر زور به ورته وښایي. هرڅوک به د اور لمبې، سیلۍ، زورور باران او د ږلۍ توفان وویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_30.mp3', '', 1761754199, 1761754199),
(52146, 'Isaiah 30:31', 'Isaiah', 30, 31, 'کله چې اشوریان د څښتن اواز واوري، نو هغوی به د هغه د سزا لرګی احساس کړي او ډېر به ووېریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_31.mp3', '', 1761754199, 1761754199),
(52147, 'Isaiah 30:32', 'Isaiah', 30, 32, 'هرځل چې څښتن په خپل لرګي په هغوی ګوزارونه کوي، نو د هغه قوم به چمبې او ربابونه وهي. خدای به په خپله د اشوریانو په وړاندې وجنګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_32.mp3', '', 1761754199, 1761754199),
(52148, 'Isaiah 30:33', 'Isaiah', 30, 33, 'ډېر پخوا د اشور پاچا د مړي د سوځولو دپاره یو ځای تیار شوی ؤ. هغه ځای ژور او پراخه دی او د لرګیو څخه ډک دی. د څښتن پوکی به لکه د اور غورځوونکي لمبو د ویالې په شان هغه ته اور واچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah30_verse_33.mp3', '', 1761754199, 1761754199),
(52149, 'Genesis 50:1', 'Genesis', 50, 1, 'یوسف په خپل پلار باندې ورپرېوت او په هغه باندې یې وژړل او ښکل یې کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_1.mp3', '', 1761754199, 1761754199),
(52150, 'Genesis 50:2', 'Genesis', 50, 2, 'بیا یوسف خپلو هغو ډاکترانو ته چې د هغه خدمت یې کاوه حکم وکړ چې د هغه پلار یعقوب مړی مومیایي کړي. نو ډاکترانو هغه مومیایي کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_2.mp3', '', 1761754199, 1761754199),
(52151, 'Genesis 50:3', 'Genesis', 50, 3, 'په دې کار باندې پوره څلوېښت ورځې ولګېدلې او د مصر خلک اویا ورځې په هغه باندې ویر وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_3.mp3', '', 1761754199, 1761754199),
(52152, 'Genesis 50:4', 'Genesis', 50, 4, 'کله چې د هغه د ویر کولو ورځې تېرې شوې، نو یوسف د فرعون درباریانو ته وویل: «که په ما مهرباني کوئ، نو زما په خاطر د فرعون سره خبرې وکړئ او هغه ته ووایئ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_4.mp3', '', 1761754199, 1761754199),
(52153, 'Genesis 50:5', 'Genesis', 50, 5, 'زما پلار ماته قسم راکړی دی چې: ‹زه مړ کېږم. ما د کنعان په خاوره کې په هغه قبر کې چې پخوا جوړ شوی ؤ، ښخ کړه.› اوس ماته اجازه راکړئ چې لاړ شم او پلار مې ښخ کړم. بیا به بېرته راشم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_5.mp3', '', 1761754199, 1761754199),
(52154, 'Genesis 50:6', 'Genesis', 50, 6, 'فرعون ځواب ورکړ: «لاړ شه او لکه څنګه چې پلار دې درته قسم درکړی دی، هغه ښخ کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_6.mp3', '', 1761754199, 1761754199),
(52155, 'Genesis 50:7', 'Genesis', 50, 7, 'نو یوسف روان شو چې خپل پلار ښخ کړي. د فرعون ټول درباریان، د دربار لوړ‌رتبه مامورین او د مصر ټول مشران د یوسف سره لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_7.mp3', '', 1761754199, 1761754199),
(52156, 'Genesis 50:8', 'Genesis', 50, 8, 'د دوی سره د یوسف د کورنۍ ټول غړي، د هغه ورونه او د هغه د پلار کورنۍ هم لاړل. یوازې د هغوی اولادونه، رمې او پادې په جوشن کې پاتې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_8.mp3', '', 1761754199, 1761754199),
(52157, 'Genesis 50:9', 'Genesis', 50, 9, 'جنګي ګاډۍ‌ګانې او په اسونو باندې سپاره خلک هم د هغوی سره لاړل او دا یوه لویه قافله وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_9.mp3', '', 1761754199, 1761754199),
(52158, 'Genesis 50:10', 'Genesis', 50, 10, 'کله چې دوی د اطاد درمند ځای ته چې د اردن د سیند په لمرخاته کې دی ورسېدل، نو ډېر سخت او په لوړ اواز یې وژړل او یوسف په هغه ځای کې د خپل پلار دپاره اووه ورځې د مړینې مراسم ونیول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_10.mp3', '', 1761754199, 1761754199),
(52159, 'Genesis 50:11', 'Genesis', 50, 11, 'کله چې د هغه ځای اوسېدونکو کنعانیانو دا ولیدل، نو هغوی وویل: «مصریان ډېر سخت ویر او ماتم کوي.» نو ځکه هغه ځای چې د اردن د سیند په لمرخاته کې دی، د آبل مصرایم په نوم یاد کړای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_11.mp3', '', 1761754199, 1761754199),
(52160, 'Genesis 50:12', 'Genesis', 50, 12, 'نو څنګه چې یعقوب وصیت کړی ؤ، زامنو یې هماغسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_12.mp3', '', 1761754199, 1761754199),
(52161, 'Genesis 50:13', 'Genesis', 50, 13, 'هغوی هغه د کنعان خاورې ته یووړ او ممري ته نژدې یې د مکفیله د پټي په سمڅه کې چې ابراهیم هغه د پټي سره د حیتي عفرون څخه د هدیرې دپاره اخیستې وه، ښخ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_13.mp3', '', 1761754199, 1761754199),
(52162, 'Genesis 50:14', 'Genesis', 50, 14, 'یوسف د خپل پلار د ښخولو څخه وروسته د خپلو ورونو او هغو ټولو خلکو سره چې د جنازې دپاره د هغه سره تللي وو، بېرته مصر ته راستون شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_14.mp3', '', 1761754199, 1761754199),
(52163, 'Genesis 50:15', 'Genesis', 50, 15, 'کله چې د یوسف ورونو ولیدل چې د هغوی پلار مړ شو، نو هغوی وویل: «که چېرې یوسف زمونږ څخه لا تر‌اوسه هم کرکه کوي او وغواړي چې د ټولو هغو بدیو بدله چې مونږ ورسره کړي دي زمونږ څخه واخلي، نو بیا به څه کوو؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_15.mp3', '', 1761754199, 1761754199),
(52164, 'Genesis 50:16', 'Genesis', 50, 16, 'نو هغوی یوسف ته پیغام ورولېږه او ویې ویل: «زمونږ پلار د خپل مرګ څخه مخکې دغه حکم کړی دی:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_16.mp3', '', 1761754199, 1761754199),
(52165, 'Genesis 50:17', 'Genesis', 50, 17, 'یوسف ته به داسې ووایئ چې زه ستا څخه دا غوښتنه کوم چې د خپلو ورونو ګناهونه او خطاګانې او هغه بد چلند چې ستا سره یې کړی دی، وبخښه. اوس زمونږ یعنې د خپل پلار د خدای د غلامانو ګناهونه وبخښه.» کله چې یوسف د هغوی پیغام تر‌لاسه کړ، نو ویې ژړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_17.mp3', '', 1761754199, 1761754199),
(52166, 'Genesis 50:18', 'Genesis', 50, 18, 'بیا د هغه ورونه په خپله راغلل او د هغه په وړاندې یې خپل سرونه ټیټ کړل او ویې ویل: «مونږ ستا غلامان یو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_18.mp3', '', 1761754199, 1761754199),
(52167, 'Genesis 50:19', 'Genesis', 50, 19, 'خو یوسف هغوی ته وویل: «مه وېرېږئ. ایا زه خدای یم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_19.mp3', '', 1761754199, 1761754199),
(52168, 'Genesis 50:20', 'Genesis', 50, 20, 'تاسو زما په خلاف د بدو پلان درلود، خو خدای هغه په نېکۍ باندې بدل کړ د دې دپاره چې د ډېرو خلکو ژوند وژغوري او لکه څنګه چې وشول هغوی نن ژوندي پاتې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_20.mp3', '', 1761754199, 1761754199),
(52169, 'Genesis 50:21', 'Genesis', 50, 21, 'نو بیا مه وېرېږئ. زه به په تاسو او ستاسو په اولادونو باندې پام کوم.» نو هغوی ته یې تسلي ورکړه او په مهربانۍ سره یې ورسره خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_21.mp3', '', 1761754199, 1761754199),
(52170, 'Genesis 50:22', 'Genesis', 50, 22, 'یوسف د خپل پلار د ټولې کورنۍ سره په مصر کې پاتې شو. هغه یوسلو لس کاله ژوند وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_22.mp3', '', 1761754199, 1761754199),
(52171, 'Genesis 50:23', 'Genesis', 50, 23, 'یوسف د افرایم د اولادونو او لمسیانو د لیدلو پورې ژوندی ؤ او همدارنګه هغه تر هغې پورې ژوندی ؤ چې د منسي د زوی ماخیر اولادونه یې هم په خپله کورنۍ کې ولیدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_23.mp3', '', 1761754199, 1761754199),
(52172, 'Genesis 50:24', 'Genesis', 50, 24, 'یوسف خپلو ورونو ته وویل: «زه مرګ ته نژدې شوی یم. خو بې له شکه چې خدای به تاسو وساتي او تاسو به له دې وطن څخه هغه وطن ته بوځي چې د ابراهیم، اسحاق او یعقوب سره یې قسم خوړلی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_24.mp3', '', 1761754199, 1761754199),
(52173, 'Genesis 50:25', 'Genesis', 50, 25, 'یوسف د یعقوب د کورنۍ خلکو ته قسم ورکړ او ویې ویل: «زما سره دا وعده وکړئ کله چې خدای تاسو هغه هېواد ته بیایي، نو زما مړی به له ځان سره وړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_25.mp3', '', 1761754199, 1761754199),
(52174, 'Genesis 50:26', 'Genesis', 50, 26, 'نو یوسف د یوسلو لس کالو په عمر په مصر کې مړ شو. وروسته له دې چې هغه یې مومیایي کړ، په تابوت کې یې کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis50_verse_26.mp3', '', 1761754199, 1761754199),
(52175, 'Job 6:3', 'Job', 6, 3, 'ځکه چې دا به د سمندر د شګو نه درانۀ وى، نو په دې وجه زما خبرې ګډې وډې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_3.mp3', '', 1761754199, 1761754199),
(52176, 'Job 6:4', 'Job', 6, 4, 'ځکه چې زۀ د قادر خُدائ په غشو باندې لګېدلے يم، د دې زهر زما په بدن کښې خوريږى، د خُدائ پاک افتونه په ما باندې راروان دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_4.mp3', '', 1761754199, 1761754199),
(52177, 'Job 6:5', 'Job', 6, 5, 'ولې زۀ د شکايت کولو حق نۀ لرم؟ ولې ځنګلى خرونه او غوَيى آواز نۀ کوى څۀ چې کله هغوئ خوراک نۀ لرى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_5.mp3', '', 1761754199, 1761754199),
(52178, 'Job 6:6', 'Job', 6, 6, 'چې څۀ څيز بې‌خونده وى نو هغه د مالګې نه بغېر خوړلے شى څۀ، يا د هګۍ په سپينو کښې څۀ مزه شته؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_6.mp3', '', 1761754199, 1761754199),
(52179, 'Job 6:7', 'Job', 6, 7, 'کله چې زۀ دې ته وګورم نو زما لوږه ختمه شى، په داسې خوراک زۀ بيمارېږم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_7.mp3', '', 1761754199, 1761754199),
(52180, 'Job 6:8', 'Job', 6, 8, 'کاش چې زما خواست منظور شى، او خُدائ پاک زما خواهش پوره کړى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_8.mp3', '', 1761754199, 1761754199),
(52181, 'Job 6:9', 'Job', 6, 9, 'زړۀ مې غواړى چې تباه مې کړى، او چې هغه خپل لاس راوږد کړى او ما ووژنى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_9.mp3', '', 1761754199, 1761754199),
(52182, 'Job 6:10', 'Job', 6, 10, 'دا به زما دپاره تسلى وى، زۀ به په بې‌رحمه درد کښې هم خوشحاله يم، ځکه چې ما به بيا هم د مقدسې هستۍ د خبرو نه اِنکار نۀ وى کړے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_10.mp3', '', 1761754199, 1761754199),
(52183, 'Job 6:11', 'Job', 6, 11, 'زما دومره طاقت نشته چې زۀ دا برداشت کړم، او چې زما څۀ اُميد نشته نو بيا زۀ ولې ژوندے يم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_11.mp3', '', 1761754199, 1761754199),
(52184, 'Job 6:12', 'Job', 6, 12, 'زما طاقت لکه د کاڼو دے څۀ؟ زما بدن د اوسپنې نه جوړ دے څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_12.mp3', '', 1761754199, 1761754199),
(52185, 'Job 6:13', 'Job', 6, 13, 'په حقيقت کښې زۀ د خپل ځان سره د مدد کولو وس نۀ لرم، او خلاصون زما نه تلے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_13.mp3', '', 1761754199, 1761754199),
(52186, 'Job 6:14', 'Job', 6, 14, 'يو کس له په کار وى چې په خپل کمزورى دوست باندې رحم وکړى، خو تاسو سره د قادر خُدائ يره نۀ وى او په ما اِلزام لګوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_14.mp3', '', 1761754199, 1761754199),
(52187, 'Job 6:15', 'Job', 6, 15, 'زما وروڼو، تاسو ما سره د خوړ په شان دوکه بازى کوئ، چې کله باران نۀ وى نو دا اوچ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_15.mp3', '', 1761754199, 1761754199),
(52188, 'Job 6:16', 'Job', 6, 16, 'چې د ويلې شوې واورې د اوبو نه ډک وى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_16.mp3', '', 1761754199, 1761754199),
(52189, 'Job 6:17', 'Job', 6, 17, 'خو د ګرمۍ په وخت کښې دا اوبۀ اوچې شى، کله چې ګرمى شى، نو دا فنا شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_17.mp3', '', 1761754199, 1761754199),
(52190, 'Job 6:18', 'Job', 6, 18, 'د اوبو لټولو دپاره قافلې خپلې لارې بدلې کړى، خو د څښلو دپاره اوبۀ نۀ وى، نو هغوئ مړۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_18.mp3', '', 1761754199, 1761754199),
(52191, 'Job 6:19', 'Job', 6, 19, 'د تيما قافلې دا اوبۀ لټوى، او د شيبا مسافر دا اُميد لرى چې اوبۀ به پېدا کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_19.mp3', '', 1761754199, 1761754199),
(52192, 'Job 6:20', 'Job', 6, 20, 'د قافلې يقين وى چې هغوئ به اوبۀ پېدا کړى، خو چې کله هلته ورسيږى نو هغوئ مايُوسه شى او اُميد يې ختم شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_20.mp3', '', 1761754199, 1761754199),
(52193, 'Job 6:21', 'Job', 6, 21, 'اوس تاسو هم د دې اوچ خوړ په شان يئ چې بې‌کاره دے، تاسو زما مصيبت وليدلو او ويرېدئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_21.mp3', '', 1761754199, 1761754199),
(52194, 'Job 6:22', 'Job', 6, 22, 'ولې ما وئيلى دى څۀ، چې ما له تُحفه راکړئ؟ يا مې د پېسو دپاره تا ته کله مِنت کړے دے څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_22.mp3', '', 1761754199, 1761754199),
(52195, 'Job 6:23', 'Job', 6, 23, 'يا دا چې د دشمن د لاس نه مې بچ کړئ؟ يا د ظالمانو نه مې خلاص کړئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_23.mp3', '', 1761754199, 1761754199),
(52196, 'Job 6:24', 'Job', 6, 24, 'ما ته وښايئ او زۀ به خاموش شم، ما پوهه کړئ چې زۀ څنګه په غلطه يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_24.mp3', '', 1761754199, 1761754199),
(52197, 'Job 6:25', 'Job', 6, 25, 'رښتيا خبرې څومره د درد نه ډکې وى. خو ستاسو د دې بحث نه مطلب څۀ دے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_25.mp3', '', 1761754199, 1761754199),
(52198, 'Job 6:26', 'Job', 6, 26, 'ستاسو خيال دا دے څۀ چې زما خبرې به صحيح کړئ، او د نا اُميده سړى خبرې بې‌مطلبه ګڼئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_26.mp3', '', 1761754199, 1761754199),
(52199, 'Job 6:27', 'Job', 6, 27, 'تاسو به يتيمان هم خرڅ کړئ، او تاسو به د خپل دوست په سر هم پېسې واخلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_27.mp3', '', 1761754199, 1761754199),
(52200, 'Job 6:28', 'Job', 6, 28, 'خو اوس ما ته وګورئ، ولې زۀ به تاسو ته دروغ وايم څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_28.mp3', '', 1761754199, 1761754199),
(52201, 'Job 6:29', 'Job', 6, 29, 'خپل سوچ بدل کړئ او بې‌اِنصافه مۀ جوړېږئ، داسې وګڼئ چې زۀ په حقه يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_29.mp3', '', 1761754199, 1761754199),
(52202, 'Job 6:30', 'Job', 6, 30, 'ستاسو څۀ خيال دے زۀ دروغ وايم څۀ؟ ستاسو په خيال کښې زۀ په رښتيا او دروغو کښې فرق نۀ شم کولے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job6_verse_30.mp3', '', 1761754199, 1761754199),
(52203, 'Exodus 3:1', 'Exodus', 3, 1, 'یوه ورځ موسی د خپل خسر یعنې د مدیان کاهن یترون رمه څروله او موسی د رمې سره د دښتې په لاره د حوریب یعنې د سینا سپېڅلي غره ته راغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_1.mp3', '', 1761754199, 1761754199),
(52204, 'Exodus 3:2', 'Exodus', 3, 2, 'هلته هغه ته د یو بوټي له منځ څخه د اور په لمبو کې د څښتن فرښته ورښکاره شوه. موسی ولیدل چې بوټي اور اخیستی ؤ، خو نه سوځېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_2.mp3', '', 1761754199, 1761754199),
(52205, 'Exodus 3:3', 'Exodus', 3, 3, 'هغه د ځان سره وویل: «دا عجیبه خبره ده! زه ځم وګورم چې دا بوټی ولې نه سوځي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_3.mp3', '', 1761754199, 1761754199),
(52206, 'Exodus 3:4', 'Exodus', 3, 4, 'کله چې څښتن ولیدل چې موسی بوټي ته ورنژدې کیږي، هغه غږ ورته وکړ: «ای موسی، ای موسی!» موسی په ځواب کې وویل: «زه حاضر یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_4.mp3', '', 1761754199, 1761754199),
(52207, 'Exodus 3:5', 'Exodus', 3, 5, 'خدای ورته وویل: «نژدې مه راځه، خپلې څپلۍ وباسه. په کومه ځمکه باندې چې ته ولاړ یې، هغه ځمکه سپېڅلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_5.mp3', '', 1761754199, 1761754199),
(52208, 'Exodus 3:6', 'Exodus', 3, 6, 'زه ستا د نیکونو ابراهیم خدای، د اسحاق خدای او د یعقوب خدای یم.» موسی خپل مخ پټ کړ، ځکه چې هغه وېرېده چې خدای ته وګوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_6.mp3', '', 1761754199, 1761754199),
(52209, 'Exodus 3:7', 'Exodus', 3, 7, 'څښتن وویل: «ما ولیدل چې زما د قوم سره په مصر کې څومره ظالمانه چلند کیږي. ما اورېدلي چې هغوی ماته زاري کوي چې د خپلو ظالمانو مشرانو څخه خلاص شي. زه د هغوی د ټولو تکلیفونو څخه خبر یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_7.mp3', '', 1761754199, 1761754199),
(52210, 'Exodus 3:8', 'Exodus', 3, 8, 'نو زه راښکته شوی یم چې هغوی د مصریانو څخه وژغورم. زه به خپل قوم د مصر څخه داسې هېواد ته بوځم چې پراخ وي او ښه حاصلخېزه ځمکه په کې وي. زه به هغوی ته هغه ځمکه ورکړم چې کنعانیان، حیتیان، اموریان، فرزیان، حویان او یبوسیان په کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_8.mp3', '', 1761754199, 1761754199);